<?php include 'db.php'; require_role('Patient'); $pid=current_entity_id($conn,'Patient'); $msg=''; if($_SERVER['REQUEST_METHOD']=='POST' && isset($_FILES['scan'])){ if(!is_dir('uploads')) mkdir('uploads'); $name=time().'_'.basename($_FILES['scan']['name']); $path='uploads/'.$name; if(move_uploaded_file($_FILES['scan']['tmp_name'],$path)){ $appid = !empty($_POST['appointment']) ? intval($_POST['appointment']) : null; $stmt=$conn->prepare("INSERT INTO FILE_UPLOAD(File_Name,File_Path,Upload_Date,Patient_ID,Appointment_ID) VALUES(?,?,CURDATE(),?,?)"); $stmt->bind_param('ssii',$name,$path,$pid,$appid); $stmt->execute(); $msg='File uploaded successfully'; } } $page_title='Upload Scan'; include 'header.php'; ?>
<h2>Upload Scan File</h2><?php if($msg) echo '<div class="alert">'.esc($msg).'</div>'; ?><form class="form" method="post" enctype="multipart/form-data"><label>Appointment</label><select name="appointment"><option value="">General Upload</option><?php $q=$conn->query("SELECT Appointment_ID, Appointment_Date FROM APPOINTMENT WHERE Patient_ID=$pid"); while($r=$q->fetch_assoc()) echo '<option value="'.$r['Appointment_ID'].'">Appointment #'.$r['Appointment_ID'].' - '.$r['Appointment_Date'].'</option>'; ?></select><input type="file" name="scan" required><button>Upload</button></form><?php include 'footer.php'; ?>